import{_ as o,H as t,f as d,i as a}from"./chunks/framework.BauLNg70.js";const u=JSON.parse('{"title":"Host API changelog","description":"","frontmatter":{},"headers":[],"relativePath":"host-api-changelog.md","filePath":"host-api-changelog.md"}'),s={name:"host-api-changelog.md"};function i(r,e,c,l,n,m){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="host-api-changelog" tabindex="-1">Host API changelog <a class="header-anchor" href="#host-api-changelog" aria-label="Permalink to &quot;Host API changelog&quot;">​</a></h1><p>Versionado SemVer del <code>HostBridge</code> que ven los mods de Snake Classic.</p><blockquote><p><strong>Contrato</strong>: el manifest de un mod declara <code>requires.hostApi: &#39;^1.0.0&#39;</code>. El loader rechaza mods cuya restricción no matchee la versión actual del juego (estado <code>incompatible</code>, mod no se activa).</p></blockquote><hr><h2 id="v1-0-0-—-lanzamiento-2026-xx-xx" tabindex="-1">v1.0.0 — Lanzamiento (2026-XX-XX) <a class="header-anchor" href="#v1-0-0-—-lanzamiento-2026-xx-xx" aria-label="Permalink to &quot;v1.0.0 — Lanzamiento (2026-XX-XX)&quot;">​</a></h2><p>Superficie inicial expuesta al modder:</p><ul><li><code>host.callHostFn(name, args)</code> — invocar funciones host registradas por el juego para mods (<code>togglePowerUp</code>, <code>setPowerUpSpawnChance</code>, <code>setSpeedBase</code>, <code>setSpeedProgression</code>).</li><li><code>host.subscribeEvent(name, cb)</code> — suscribir a eventos del juego listados en <code>policy.surfaces.events.subscribe</code>. Snake Classic expone: <code>GAME_STARTED</code>, <code>POWERUP_SPAWNED</code>, <code>GAME_OVER</code>, <code>SCORE_INCREASED</code>, <code>SNAKE_DIED</code>.</li><li><code>host.registerHook(name, fn)</code> — registrar hooks del lifecycle del mod (<code>onActivate</code>, <code>onDeactivate</code>).</li><li><code>host.state.read(path)</code> — lectura <strong>read-only</strong> del state del juego por path canónico. Snake Classic expone las siguientes 7 paths (convención <code>SCREAMING_SNAKE_CASE__DOUBLE_UNDERSCORE</code> del state store del juego): <ul><li><code>GAME_DATA__RUN__SCORE__CURRENT</code> — score actual de la partida.</li><li><code>GAME_DATA__RUN__SCORE__MULTIPLIER</code> — multiplicador activo.</li><li><code>GAME_DATA__RUN__SPEED__LEVEL</code> — nivel de velocidad.</li><li><code>GAME_DATA__RUN__SNAKE__LENGTH</code> — longitud de la serpiente.</li><li><code>GAME_DATA__RUN__POWERUP__ACTIVE</code> — power-up activo (o null).</li><li><code>GAME_DATA__RUN__POWERUP__ACTIVE_VARIANT</code> — variante del activo.</li><li><code>GAME_DATA__APP_SYNC__PROGRESS__HIGH_SCORE</code> — high score persistido.</li></ul></li><li><code>host.storage.{get,set,delete,keys}(...)</code> — storage aislado por mod, quota declarada en <code>permissions.storage.quotaKb</code>.</li><li><code>host.i18n.{register,t}(...)</code> — traducciones del mod (si declara <code>permissions.i18n</code>).</li><li><code>host.log.{debug,info,warn,error}(...)</code> — logger (no afecta al bus de error del juego).</li><li><code>host.analytics.track(name, props)</code> — eventos custom declarados en <code>mod.json#analytics.events</code>.</li><li><code>host.registerSettingsTab(descriptor)</code> — tabs declarativos en <code>Settings → Mods → &lt;tu tab&gt;</code>. Catálogo de componentes UI en <a href="/mod-portal-snake-classic/storybook/">/storybook/</a>.</li><li><code>host.registerPowerUp(def)</code> — registrar power-ups nuevos (si declaras <code>permissions.powerups.actions: [&#39;register&#39;]</code>).</li><li><code>host.registerAsset(kind, id, source)</code> — sustituir imágenes / audio / fonts (si declaras <code>permissions.assets</code>).</li></ul><h3 id="eventos-mod-framework-emitidos-por-el-runtime" tabindex="-1">Eventos <code>mod.framework.*</code> emitidos por el runtime <a class="header-anchor" href="#eventos-mod-framework-emitidos-por-el-runtime" aria-label="Permalink to &quot;Eventos `mod.framework.*` emitidos por el runtime&quot;">​</a></h3><p>20 eventos canónicos automáticos (no participación del modder). Listado completo en <a href="https://github.com/leteoworks/my-game-fw/blob/main/src/modules/mod-runtime/telemetry/framework-events.ts" target="_blank" rel="noreferrer">framework-events.ts</a>. Resumen:</p><ul><li><strong>Discovery + lifecycle</strong> (8): <code>discovered</code>, <code>validated_ok</code>, <code>upgrade</code>, <code>removed</code>, <code>activated</code>, <code>deactivated</code>, <code>permission_prompt_shown</code>, <code>permission_decision</code>, <code>session_summary</code>.</li><li><strong>Engagement</strong> (2): <code>engagement_tick</code>, <code>first_use_ever</code>.</li><li><strong>Errores + límites</strong> (3): <code>fault_summary</code>, <code>quota_hit</code>, <code>api_violation</code>.</li><li><strong>Performance</strong> (7): <code>perf.frame_impact</code>, <code>perf.cpu_budget</code>, <code>perf.memory_high_water</code>, <code>perf.hook_slow</code>, <code>perf.long_task_attributed</code>, <code>perf.budget_exceeded</code>, <code>perf.throttled</code>.</li></ul><h3 id="no-disponible-en-v1-0-0" tabindex="-1">NO disponible en v1.0.0 <a class="header-anchor" href="#no-disponible-en-v1-0-0" aria-label="Permalink to &quot;NO disponible en v1.0.0&quot;">​</a></h3><ul><li><code>fetch</code> o <code>XMLHttpRequest</code> directos — el sandbox los bloquea.</li><li><code>window</code>, <code>document</code>, <code>localStorage</code>.</li><li><code>host.state.write(...)</code> — Snake Classic v1.0.0 <strong>solo expone lectura</strong> (<code>state.read</code>). Si necesitas modificar el state, hazlo vía eventos (<code>host.subscribeEvent</code> + <code>host.callHostFn</code> que el juego expone como contrato).</li><li>Networking arbitrario — <code>host.http.request</code> existe pero solo si declaras <code>permissions.network</code> y el host está en allowlist.</li><li>Backend clients (leaderboards, save sync) — gated por <code>permissions.backend-client</code> (no expuesto en Snake Classic v1.0.0).</li></ul><hr><h2 id="politica-de-versionado" tabindex="-1">Política de versionado <a class="header-anchor" href="#politica-de-versionado" aria-label="Permalink to &quot;Política de versionado&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cambio</th><th>SemVer bump</th></tr></thead><tbody><tr><td>Añadir helper nuevo a <code>host.*</code></td><td>MINOR</td></tr><tr><td>Añadir surface declarada en <code>policy.ts</code></td><td>MINOR (los mods existentes no piden, no se rompen)</td></tr><tr><td>Cambiar shape de un helper existente</td><td>MAJOR (rompe mods que lo usan)</td></tr><tr><td>Eliminar un helper</td><td>MAJOR</td></tr><tr><td>Añadir error code nuevo</td><td>MINOR</td></tr><tr><td>Cambiar error code existente</td><td>MAJOR</td></tr><tr><td>Cambios solo en el manifest del juego (no expuestos al mod)</td><td>sin bump</td></tr></tbody></table><p>Cualquier MAJOR bump requiere documentar la migración en esta página antes de mergear el cambio al runtime.</p><hr><h2 id="cross-links" tabindex="-1">Cross-links <a class="header-anchor" href="#cross-links" aria-label="Permalink to &quot;Cross-links&quot;">​</a></h2><ul><li><a href="/mod-portal-snake-classic/api-reference">api-reference</a></li><li><a href="/mod-portal-snake-classic/manifest-format">manifest-format</a></li><li><a href="https://github.com/leteoworks/my-game-fw/blob/main/docs/mods/philosophy.md" target="_blank" rel="noreferrer">Filosofía del sistema (monorepo)</a></li></ul>',19)])])}const h=o(s,[["render",i]]);export{u as __pageData,h as default};
